    def __init__(self, toks):
        self.toks = toks
        self.i = 0

    def peek(self):
        return self.toks[self.i] if self.i < len(self.toks) else (None, None)

    def take(self):
        t = self.peek()
        self.i += 1
        return t

    def parse(self):
        e = self.expr()
        if self.i != len(self.toks):
            raise ValueError("trailing tokens")
        return e

    def expr(self):
        e = self.term()
        while self.peek()[0] in ("+", "-"):
            op = self.take()[0]
            r = self.term()
            e = ("+", e, r) if op == "+" else ("-", e, r)
        return e

    def term(self):
        e = self.factor()
        while self.peek()[0] == "*":
            self.take()
            e = ("*", e, self.factor())
        return e

    def factor(self):
        if self.peek()[0] == "-":
            self.take()
            return ("neg", self.factor())
        return self.atom()

    def atom(self):
        k, v = self.take()
        if k == "num":
            return ("num", v)
        if k == "var":
            return ("var", v)
        if k == "(":
            e = self.expr()
            if self.take()[0] != ")":
                raise ValueError("missing ')'")
            return e
        raise ValueError(f"unexpected token {k!r}")


