    kind = e[0]
    if kind == "num":
        return {(): e[1]} if e[1] else {}
    if kind == "var":
        return {(e[1],): 1}
    if kind == "neg":
        return {k: -c for k, c in to_poly(e[1]).items()}
    if kind == "+":
        p1, p2 = to_poly(e[1]), to_poly(e[2])
        out = dict(p1)
        for k, c in p2.items():
            out[k] = out.get(k, 0) + c
